VIDEO = {'footer': 'Cross-Site Request Forgery with Spring Security  ·  Security Basics  ·  Java', 'poster': {'headline': [('CSRF WITH', 'text'), ('SPRING SECURITY', 'accent')], 'taglines': [("Spring Security's token check is on by default, and the ways to lose it are a switch, an e", 'gold')], 'before': {'code': 'http.csrf(c -> c.disable())', 'note': 'CSRF protection switched off', 'tag': 'BEFORE'}, 'after': {'code': 'csrf.ignoringRequestMatchers(...)', 'note': 'The bill', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['THE RESPONSE'], 'console_amber': ['THE REQUEST', 'THE API REQUESTS', 'ONE BYTE OF IT', 'EACH STATE-CHANGING'], 'console_cyan': ['THE CONFIGURATION', 'ANA SIGNS IN', 'THE SIGN-IN FORM', 'HOW THE', 'THE COOKIE', 'THE SESSION COOKIE', 'WITH server']}}
